    LoginV2Component.prototype.loginRoles = function () {
        var _this = this;
        if (this.loginForm.valid) {
            this.spinner.show();
            this.authService.loginRoles(this.loginForm.value).subscribe(function (res) {
                // console.log('Login: ', res);
                if (res.status == 'OK') {
                    if (res.object) {
                        var userDetails = res.object;
                        // console.log("USER DETAILS: ", userDetails);
                        localStorage.setItem('jwtToken', res.authToken.token);
                        localStorage.setItem('loginResponse', JSON.stringify(res));
                        localStorage.setItem('userName', res.object.name);
                        localStorage.setItem('serviceId', res.object.serviceId);
                        localStorage.setItem("department", _this.ac);
                        localStorage.setItem('userType', userDetails.loginId);
                        if (_this.loginType == 'trg-team') {
                            if (userDetails.moduleList) {
                                _this.setRoleModule(userDetails, 'TRG Team', 1);
                            }
                            _this.router.navigate(['/main/trg-team/dashboard']);
                            localStorage.setItem('welcomeRoute', '/main/trg-team/dashboard');
                            // localStorage.setItem('userDept',"1")
                        }
                        else if (_this.loginType == 'trg-battalion') {
                            if (userDetails.moduleList) {
                                _this.setRoleModule(userDetails, 'TRG Battalion', 2);
                            }
                            _this.router.navigate(['/main/trg-battalion/dashboard']);
                            localStorage.setItem('welcomeRoute', '/main/trg-battalion/dashboard');
                        }
                        else if (_this.loginType == 'academic-depart') {
                            if (userDetails.moduleList) {
                                _this.setRoleModule(userDetails, 'Academic Department', 4);
                            }
                            _this.router.navigate(['/main/academic-depart/dashboard']);
                            localStorage.setItem('welcomeRoute', '/main/academic-depart/dashboard');
                        }
                        else if (_this.loginType == 'adjutant-branch') {
                            if (userDetails.moduleList) {
                                _this.setRoleModule(userDetails, 'Adjutant Branch', 12);
                            }
                            _this.router.navigate(['/main/adjutant-branch/dashboard']);
                            localStorage.setItem('welcomeRoute', '/main/adjutant-branch/dashboard');
                        }
                        else if (_this.loginType == 'gs-branch') {
                            if (userDetails.moduleList) {
                                _this.setRoleModule(userDetails, 'GS Branch', 10);
                            }
                            _this.router.navigate(['/main/gs-branch/dashboard']);
                            localStorage.setItem('welcomeRoute', '/main/gs-branch/dashboard');
                        }
                        _this.spinner.hide();
                    }
                    else {
                        _this.spinner.hide();
                        _this.sharedService.openErrorSnackbarWithSeconds("Invalid Username of Password!", 5);
                    }
                }
                else {
                    _this.spinner.hide();
                    _this.sharedService.openSnackbar(res.message);
                }
            }, function (err) {
                _this.spinner.hide();
                _this.sharedService.openSnackbar('Some Error Occured.');
                console.log(JSON.stringify(err));
            });
        }
        else {
            this.isError = true;
        }
    };
